import * as T from './vendor/three.module.js';
import {groundedBody} from './grounding.js';
export function photoPose(bear,kind,t){const {body,arms,legs}=bear;body.position.y=groundedBody([0,0]);body.rotation.set(0,0,Math.sin(t*2)*.018);legs.forEach(g=>g.rotation.set(0,0,0));arms.forEach(g=>{g.rotation.set(0,0,0);g.scale.set(1,1,1)});if(kind==='wave'){arms[1].rotation.set(-2.45,Math.sin(t*5)*.22,-.36);arms[0].rotation.z=.08}else if(kind==='heart'){for(let i=0;i<2;i++){const arm=arms[i],target=new T.Vector3((i?1:-1)*.05,.62,.34).sub(arm.position);arm.quaternion.setFromUnitVectors(new T.Vector3(0,-1,0),target.normalize())}}else if(kind==='chin'){arms[0].quaternion.setFromUnitVectors(new T.Vector3(0,-1,0),new T.Vector3(.21,.09,.25).normalize());body.rotation.z=.08}bear.relax?.(true)}
